// TestTransferFunctionDescriptorStiffHighDegreeStaysNil checks that the
// split's TF of a strictly proper degree-20 model is certified with nil and
// within the stored response's terms at 320 bits.
func TestTransferFunctionDescriptorStiffHighDegreeStaysNil(t *testing.T) {
	sys := stiffStrictlyProper20.system(t)
	if _, route, _ := sys.transferRationalRoute(nil); route != tfRouteStiff {
		t.Fatalf("route %d, want the split of the ill-conditioned E", route)
	}
	res, err := sys.TransferFunction(nil)
	if err != nil {
		t.Fatalf("TransferFunction: %v", err)
	}
	if d := len(res.TF.Den[0]) - 1; d < 20 {
		t.Fatalf("denominator degree %d, want ≥ 20", d)
	}
	if worst, at := withinTermsWorst(t, sys, res.TF, math.Inf(1)); worst > 1 {
		t.Errorf("%.3g× the refute threshold at %v", worst, at)
	}
}
